package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TaskCost085Test {
    static final String ID="c68c7c0a-0000-4000-8000-000000000085";
    static JSONObject model(){var m=TaskCost084Test.model(3).put("version",TaskCost085.VERSION);int i=0;for(Object raw:m.getJSONArray("pairs"))((JSONObject)raw).put("receiptId",ID).put("memoryBankEntries",1+2*i++);return m.put("setup085",TaskCost085.setup(m.getJSONArray("pairs"),125));}
    static JSONObject candidate(){return TaskCost080Test.candidate().put("id",ID);}
    static JSONObject estimate(JSONObject m,int n){return TaskCost085.estimate(candidate(),TaskCost080Test.spec(0),TaskCost080Test.workload(),m,n);}
    @Test public void repeatMathIsPreservedWithinMeasuredBank(){var m=model();var e=estimate(m,8);var baseline=TaskCost084.estimate(candidate(),TaskCost080Test.spec(0),TaskCost080Test.workload(),WorldFrames.copy(m).put("version",TaskCost084.VERSION));assertTrue(e.getBoolean("available"));assertEquals(baseline.getDouble("savingMillis"),e.getDouble("savingMillis"),0);assertEquals(baseline.getDouble("marginMillis"),e.getDouble("marginMillis"),0);assertEquals(0,e.getDouble("bankGrowthMarginMillis"),0);assertEquals(WorldFrames.hash(m),e.getString("modelSha256"));}
    @Test public void growthWidensRangeAndNeverCreatesBenefit(){var m=model();var a=estimate(m,11);var b=estimate(m,17);assertEquals(a.getDouble("savingMillis"),b.getDouble("savingMillis"),0);assertTrue(b.getDouble("marginMillis")>a.getDouble("marginMillis"));assertEquals(6*b.getDouble("bankSensitivityMillisPerEntry"),b.getDouble("bankGrowthMarginMillis"),1e-9);assertTrue(b.getDouble("lowerSavingMillis")<a.getDouble("lowerSavingMillis"));}
    @Test public void sensitivityHasFloorWithoutCallingItCausal(){var m=model();for(Object raw:m.getJSONArray("pairs")){var p=(JSONObject)raw;p.put("memoryMillis",7000).put("savingMillis",p.getDouble("simpleMillis")-7000);}m.put("setup085",TaskCost085.setup(m.getJSONArray("pairs"),0));assertEquals(25,estimate(m,12).getDouble("bankSensitivityMillisPerEntry"),0);}
    @Test public void explicitChoiceSurvivesANewerNearestMemory(){var old=candidate().put("distance",.04);var newer=candidate().put("id","c68c7c0a-0000-4000-8000-000000000086").put("distance",0);var candidates=new JSONArray().put(newer).put(old);var d=TaskCost085.choose(TaskCost080Test.spec(0),"memory",candidates,TaskCost080Test.workload(),new JSONObject(),ID,2);assertEquals(ID,d.getJSONObject("candidate").getString("id"));assertEquals(2,d.getJSONArray("candidates").length());assertTrue(d.getBoolean("useMemory"));assertEquals(ID,d.getString("requestedReceipt085"));}
    @Test public void invalidOrMissingSelectionCannotSilentlyChangeProcedure(){for(String id:new String[]{"../bad","1-1-1-1-1"})assertThrows(IllegalArgumentException.class,()->TaskCost085.validateSelection("memory",id));for(String mode:new String[]{"simple","adaptive"})assertThrows(IllegalArgumentException.class,()->TaskCost085.validateSelection(mode,ID));assertThrows(IllegalArgumentException.class,()->TaskCost085.choose(TaskCost080Test.spec(0),"memory",new JSONArray(),TaskCost080Test.workload(),new JSONObject(),ID,1));assertThrows(IllegalArgumentException.class,()->TaskCost085.choose(TaskCost080Test.spec(0),"memory",new JSONArray().put(candidate().put("distance",.11)),TaskCost080Test.workload(),new JSONObject(),ID,1));}
    @Test public void defaultChoiceStillUsesExistingNearestRule(){var cs=new JSONArray().put(candidate());var a=Procedure079.choose(TaskCost080Test.spec(0),"memory",cs);var b=TaskCost085.choose(TaskCost080Test.spec(0),"memory",cs,TaskCost080Test.workload(),new JSONObject(),"",1);assertTrue(a.similar(b));assertFalse(TaskCost085.choose(TaskCost080Test.spec(0),"simple",new JSONArray(),TaskCost080Test.workload(),new JSONObject(),"",0).getBoolean("useMemory"));}
    @Test public void bankCountRequiresOriginalMeasuredJob(){var s=TaskCost080Test.measured("s","simple",1000,0);var m=TaskCost080Test.measured("m","memory",900,0);var j=new JSONObject().put("bankSnapshot",new JSONArray().put(new JSONObject().put("id","owned-memory")));m.put("jobSha256",WorldFrames.hash(j));assertEquals(1,TaskCost085.pair(s,m,j).getInt("memoryBankEntries"));j.getJSONArray("bankSnapshot").put(new JSONObject().put("id","another"));assertThrows(IllegalArgumentException.class,()->TaskCost085.pair(s,m,j));}
    @Test public void setupCannotBeUnderreported(){var m=model();double expected=125;for(Object raw:m.getJSONArray("pairs")){var p=(JSONObject)raw;expected+=p.getDouble("simpleMillis")+p.getDouble("memoryMillis");}assertEquals(expected,m.getJSONObject("setup085").getDouble("totalMillis"),0);TaskCost085.verifySetup(m);m.getJSONObject("setup085").put("totalMillis",1);assertThrows(IllegalStateException.class,()->estimate(m,8));}
    @Test public void paybackNeedsPositiveLowerSavingAndChargesSetup(){var m=model();var no=TaskCost085.payback(m,new JSONObject().put("lowerSavingMillis",-1));assertFalse(no.getBoolean("available"));assertFalse(no.has("tasks"));var yes=TaskCost085.payback(m,new JSONObject().put("lowerSavingMillis",1000));assertEquals(Math.ceil(m.getJSONObject("setup085").getDouble("totalMillis")/1000),yes.getDouble("tasks"),0);}
    @Test public void workloadVersionAndBudgetBoundariesRemainUnavailable(){assertFalse(estimate(model().put("version",TaskCost084.VERSION),8).getBoolean("available"));assertFalse(estimate(model(),33).getBoolean("available"));assertFalse(TaskCost085.estimate(candidate(),TaskCost080Test.spec(0),TaskCost080Test.workload().put("retain",true),model(),8).getBoolean("available"));}
    @Test public void coverageReportsInvestmentWithoutActionAuthority(){var c=CalibrationCoverage083.describe(model());assertTrue(c.has("setup085"));assertTrue(c.getJSONArray("groups").getJSONObject(0).getBoolean("repeatCountMet"));assertFalse(c.has("useMemory"));}
}
